<script setup lang="ts">
import {ref,onBeforeUnmount} from 'vue'
import {chooseFolder} from '../lib/storage'
import {runContainerInWorker} from '../lib/container-client'
import {workspace} from '../core/workspace'
import {friendlyError,humanBytes} from '../lib/format'
import type {ContainerOutput} from '../lib/container-ops'
const mode=ref<'trim'|'merge'>('trim'),files=ref<File[]>([]),start=ref(0),end=ref(1),busy=ref(false),progress=ref(0),message=ref(''),error=ref(''),result=ref<ContainerOutput[]>([])
let ctrl:AbortController|null=null
function pick(){const input=document.createElement('input');input.type='file';input.multiple=mode.value==='merge';input.accept='.mp4,.m4v,.mov';input.onchange=()=>{files.value=Array.from(input.files??[]).slice(0,50);result.value=[]};input.click()}
function move(i:number,delta:number){const next=i+delta;if(next<0||next>=files.value.length)return;const copy=[...files.value];[copy[i],copy[next]]=[copy[next],copy[i]];files.value=copy}
async function run(){if(busy.value||!files.value.length)return;busy.value=true;error.value='';result.value=[];progress.value=0;const ctl=new AbortController();ctrl=ctl;try{const root=await chooseFolder(),folder=await root.getDirectoryHandle('frameslice-edit-'+crypto.randomUUID(),{create:true});const file=files.value[0];await workspace.run('remux',file,ctl.signal,ctx=>runContainerInWorker({file,folder,action:mode.value,format:'mp4',selectedIds:[],acknowledgeUnlisted:false,range:{start:start.value,end:end.value},mergeFiles:[...files.value]},ctl.signal,{onProgress:(p,l)=>{progress.value=p;message.value=l;ctx.progress(p,l)},onOutput:o=>{result.value.push(o);ctx.checkpoint(o.filename)}}));message.value='处理及深度校验完成';progress.value=1}catch(e){error.value=friendlyError(e)}finally{busy.value=false;ctrl=null}}
onBeforeUnmount(()=>ctrl?.abort())
</script>
<template><section class="fs-analysis"><div class="fs-analysis-header"><strong>无损剪辑与合并（实验功能）</strong><select v-model="mode" :disabled="busy" @change="files=[];result=[]"><option value="trim">区间截取</option><option value="merge">顺序合并</option></select></div><p class="fs-analysis-disclaimer">{{mode==='trim'?'精确输入真实 GOP 起止时间，终点可为视频结束；不自动重编码或吸附。':'首版仅支持编码配置一致、单视频轨且无音轨/字幕轨的 MP4/MOV；不兼容时拒绝。'}}</p><button class="secondary-button" :disabled="busy" @click="pick">选择{{mode==='merge'?'多个':''}}视频</button><div v-for="(file,i) in files" :key="i" class="fs-job-row"><strong>{{i+1}}. {{file.name}} · {{humanBytes(file.size)}}</strong><div v-if="mode==='merge'"><button class="secondary-button" :disabled="busy||i===0" @click="move(i,-1)">上移</button><button class="secondary-button" :disabled="busy||i===files.length-1" @click="move(i,1)">下移</button></div></div><div v-if="mode==='trim'" class="fs-center-toolbar"><label>起始秒 <input v-model.number="start" type="number" step="any" min="0" :disabled="busy"/></label><label>结束秒 <input v-model.number="end" type="number" step="any" min="0" :disabled="busy"/></label></div><button v-if="!busy" class="primary-button" :disabled="files.length<(mode==='merge'?2:1)" @click="run">选择目录并执行</button><button v-else class="secondary-button" @click="ctrl?.abort()">取消</button><p role="status">{{message}}</p><progress v-if="busy" :value="progress" max="1"/><p v-if="error" role="alert" class="fs-analysis-warning">{{error}}</p><p v-for="item in result" :key="item.filename">{{item.filename}} · {{humanBytes(item.bytes)}}</p></section></template>
